    public static void lesson2701() {
        MegaProjetoJava.header("LIÇÃO 2701 — Debug / prática 01");
        System.out.println(MegaProjetoJava.BOLD + "CONCEITO" + MegaProjetoJava.RESET);
        System.out.println("Breakpoint pausa a execução.");
        System.out.println("Variação #1: leia, execute e mude os valores no seu editor.");
        System.out.println();
        System.out.println(MegaProjetoJava.BOLD + "EXEMPLO" + MegaProjetoJava.RESET);
        System.out.println("int antes1 = 92; int depois1 = antes1 + 1; System.out.println(antes1 + \" -> \" + depois1);");
        System.out.println();
        System.out.println(MegaProjetoJava.BOLD + "DESAFIO" + MegaProjetoJava.RESET);
        System.out.println("Coloque breakpoint antes e depois da atribuição.");
        System.out.println("Pergunta: o que muda se você alterar o caso de entrada?");
        System.out.println("Dica: teste pelo menos três casos diferentes.");
        System.out.println("Conceito relacionado: Debug.");
        MegaProjetoJava.pause();
    }

